 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find rectangular frames: each is a monochrome, one-cell-thick outline.
    frames = []
    for color in sorted({v for row in grid for v in row if v != 0}):
        rows = [r for r in range(h) if color in grid[r]]
        cols = [c for c in range(w) if any(grid[r][c] == color for r in range(h))]
        if len(rows) < 2 or len(cols) < 2:
            continue
        r0, r1, c0, c1 = min(rows), max(rows), min(cols), max(cols)
        # Restrict to the outline's bounding box and verify complete edges.
        if all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0, c1 + 1)) and \
           all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0, r1 + 1)):
            frames.append((color, r0, r1, c0, c1))
    # Remove duplicate detections; frame outlines are distinct colors/boxes.
    frames = list(dict.fromkeys(frames))
    out = [[0] * w for _ in range(h)]
    for color, r0, r1, c0, c1 in frames:
        for c in range(c0, c1 + 1):
            out[r0][c] = out[r1][c] = color
        for r in range(r0, r1 + 1):
            out[r][c0] = out[r][c1] = color
    frame_colors = {f[0] for f in frames}
    counts = Counter(v for row in grid for v in row if v != 0 and v not in frame_colors)
    # The two signal colors are the two most frequent non-frame colors.
    signal = [color for color, _ in counts.most_common(2)]
    if len(frames) >= 2 and len(signal) >= 2:
        # Sparse signal fills the smaller frame; dense signal fills the larger.
        signal.sort(key=lambda color: counts[color])
        ordered_frames = sorted(frames, key=lambda f: (f[2]-f[1]+1) * (f[4]-f[3]+1))
        for frame, fill in zip(ordered_frames, signal):
            _, r0, r1, c0, c1 = frame
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    if (r + c) % 2 == 0:
                        out[r][c] = fill
    return out
